"use strict";
// age
let age = 25;
console.log(age);
// integer
let marks = 90;
console.log(marks);
// float
let perentage = 90.5;
console.log(perentage);
// Negative Int/Float
let temp = -2.5;
console.log(temp);
// NaN
let result = 0 / 0;
console.log(result);
// Infinity
let inf = 10 / 0;
console.log(inf);
